  dependency jsonb; source_spec jsonb; actual jsonb; saved jsonb; expected_item jsonb; expected_creature jsonb;
  sources_before jsonb := '{}'; dependencies_before jsonb := '{}'; sources_after jsonb := '{}';
  items_before jsonb; creatures_before jsonb; item_id bigint; creature_id bigint; changed integer;
begin
  lock table public.content_update in share mode;
  -- Table gates protect duplicate detection and the preservation snapshots.
  lock table public.creature,public.item in share row exclusive mode;
  for dependency in select value from jsonb_array_elements(spec->'dependencies') order by value->>'table',(value->>'id')::bigint loop
    execute format('select to_jsonb(r)||jsonb_build_object(''uuid'',r.uuid::text) from public.%I r where r.id=$1 for share',dependency->>'table') into actual using (dependency->>'id')::bigint;
    if actual is null or exists(select 1 from jsonb_each(dependency->'expected') e where actual->e.key is distinct from e.value)
    or exists(select 1 from jsonb_each(dependency->'metadata') e where actual#>array['meta_data',e.key] is distinct from e.value)
    or exists(select 1 from jsonb_array_elements_text(dependency->'metadata_absent') k where coalesce(actual->'meta_data','{}') ? k) then raise exception 'treasure-vault-oozeform-chair: dependency drift %',dependency->>'id'; end if;
    dependencies_before:=jsonb_set(dependencies_before,array[(dependency->>'table')||':'||(dependency->>'id')],actual-'updated_at',true);
  end loop;
  for source_spec in select value from jsonb_array_elements(spec->'sources') order by (value->>'id')::bigint loop
    select to_jsonb(s) into actual from public.content_source s where s.id=(source_spec->>'id')::bigint for update;
    if actual is null or jsonb_typeof(actual->'meta_data') is distinct from 'object' or exists(select 1 from jsonb_each(source_spec) e where actual->e.key is distinct from e.value) then raise exception 'treasure-vault-oozeform-chair: source drift'; end if;
    sources_before:=jsonb_set(sources_before,array[source_spec->>'id'],actual-'updated_at',true);
  end loop;
  expected_item:=(spec->'item')||jsonb_build_object('uuid',spec#>>'{item,uuid}');
  expected_creature:=(spec->'creature')||jsonb_build_object('uuid',spec#>>'{creature,uuid}');
  -- A UUID collision anywhere is rejected; homebrew copies with other UUIDs remain untouched.
  if (select count(*) from public.item where uuid=(spec#>>'{item,uuid}')::bigint)>1 or (select count(*) from public.creature where uuid=(spec#>>'{creature,uuid}')::bigint)>1 then raise exception 'treasure-vault-oozeform-chair: duplicate UUID'; end if;
  select id into item_id from public.item where uuid=(spec#>>'{item,uuid}')::bigint;
  select id into creature_id from public.creature where uuid=(spec#>>'{creature,uuid}')::bigint;
  if (item_id is null) is distinct from (creature_id is null) then raise exception 'treasure-vault-oozeform-chair: partial import'; end if;
  if exists(select 1 from public.item r left join public.content_source s on s.id=r.content_source_id where r.id is distinct from item_id and lower(btrim(r.name))=lower(btrim(spec#>>'{item,name}')) and (s.id is null or s.user_id is null))
    or exists(select 1 from public.creature r left join public.content_source s on s.id=r.content_source_id where r.id is distinct from creature_id and lower(btrim(r.name))=lower(btrim(spec#>>'{creature,name}')) and (s.id is null or s.user_id is null)) then raise exception 'treasure-vault-oozeform-chair: existing official or orphan identity requires review'; end if;
  if exists(select 1 from public.content_update u where coalesce(u.status->>'state','PENDING') not in ('APPROVED','REJECTED') and (
  (u.type='content-source' and exists(select 1 from jsonb_array_elements(spec->'sources') s where u.ref_id=(s->>'id')::bigint or u.data->>'id'=s->>'id' or u.data->>'name'=s->>'name'))
  or exists(select 1 from jsonb_array_elements(spec->'dependencies') d where u.type=d->>'queue_type' and (u.ref_id=(d->>'id')::bigint or u.data->>'id'=d->>'id' or u.data->>'uuid'=d#>>'{expected,uuid}' or ((u.content_source_id=(d#>>'{expected,content_source_id}')::bigint or u.data->>'content_source_id'=d#>>'{expected,content_source_id}') and lower(btrim(u.data->>'name'))=lower(btrim(d#>>'{expected,name}')))))
  or (u.type in ('item','creature') and (u.data->>'uuid'=spec#>>array[u.type,'uuid'] or u.ref_id=case when u.type='item' then item_id else creature_id end or u.data->>'id'=case when u.type='item' then item_id::text else creature_id::text end or ((u.content_source_id=16 or u.data->>'content_source_id'='16') and lower(btrim(u.data->>'name'))=lower(btrim(spec#>>array[u.type,'name'])))))
)) then raise exception 'treasure-vault-oozeform-chair: pending content requires review'; end if;
  actual:=sources_before->'16';
  if item_id is not null then
    if not ((actual#>'{meta_data,counts}') @> (spec->'terminal_counts')) then raise exception 'treasure-vault-oozeform-chair: replay counts drift'; end if;
    expected_creature:=jsonb_set(expected_creature,'{operations}',(select jsonb_agg(case when e.value->>'id'=spec->>'attack_operation_id' then jsonb_set(e.value,'{data,itemId}',to_jsonb(item_id)) else e.value end order by e.position) from jsonb_array_elements(expected_creature->'operations') with ordinality e(value,position)));
    select (to_jsonb(r)||jsonb_build_object('uuid',r.uuid::text))-'{id,created_at,updated_at,search_tsv}'::text[] into saved from public.item r where r.id=item_id;
    if saved is distinct from expected_item then raise exception 'treasure-vault-oozeform-chair: replay item drift'; end if;
    select (to_jsonb(r)||jsonb_build_object('uuid',r.uuid::text))-'{id,created_at,updated_at,search_tsv}'::text[] into saved from public.creature r where r.id=creature_id;
    if saved is distinct from expected_creature then raise exception 'treasure-vault-oozeform-chair: replay creature drift'; end if;
    return;
  end if;
  if not ((actual#>'{meta_data,counts}') @> (spec->'baseline_counts')) then raise exception 'treasure-vault-oozeform-chair: baseline counts drift'; end if;
  select coalesce(jsonb_object_agg(r.id::text,to_jsonb(r)-'{updated_at,search_tsv}'::text[]),'{}') into items_before from public.item r;
  select coalesce(jsonb_object_agg(r.id::text,to_jsonb(r)-'{updated_at,search_tsv}'::text[]),'{}') into creatures_before from public.creature r;
  insert into public.item("name","bulk","level","rarity","description","group","hands","size","craft_requirements","usage","meta_data","operations","content_source_id","version","uuid","price","traits","availability") select r."name",r."bulk",r."level",r."rarity",r."description",r."group",r."hands",r."size",r."craft_requirements",r."usage",r."meta_data",r."operations",r."content_source_id",r."version",r."uuid",r."price",r."traits",r."availability" from jsonb_populate_record(null::public.item,expected_item) r returning id into item_id;
  expected_creature:=jsonb_set(expected_creature,'{operations}',(select jsonb_agg(case when e.value->>'id'=spec->>'attack_operation_id' then jsonb_set(e.value,'{data,itemId}',to_jsonb(item_id)) else e.value end order by e.position) from jsonb_array_elements(expected_creature->'operations') with ordinality e(value,position)));
  insert into public.creature("name","level","rarity","meta_data","content_source_id","version","uuid","inventory","notes","details","roll_history","operations","abilities_base","spells","deprecated","abilities_added","experience","hp_current","hp_temp","stamina_current","resolve_current","operation_data","type") select r."name",r."level",r."rarity",r."meta_data",r."content_source_id",r."version",r."uuid",r."inventory",r."notes",r."details",r."roll_history",r."operations",r."abilities_base",r."spells",r."deprecated",r."abilities_added",r."experience",r."hp_current",r."hp_temp",r."stamina_current",r."resolve_current",r."operation_data",r."type" from jsonb_populate_record(null::public.creature,expected_creature) r returning id into creature_id;
  sources_after:=sources_before;
  sources_after:=jsonb_set(sources_after,'{16,meta_data,counts,item}',spec#>'{terminal_counts,item}');
  sources_after:=jsonb_set(sources_after,'{16,meta_data,counts,creature}',spec#>'{terminal_counts,creature}');
  update public.content_source s set meta_data=(sources_after#>'{16,meta_data}')::json where s.id=16 and (to_jsonb(s)-'updated_at') is not distinct from sources_before->'16';
  get diagnostics changed=row_count;
  if changed<>1 then raise exception 'treasure-vault-oozeform-chair: source captured CAS failed'; end if;
  select (to_jsonb(r)||jsonb_build_object('uuid',r.uuid::text))-'{id,created_at,updated_at,search_tsv}'::text[] into saved from public.item r where r.id=item_id;
  if saved is distinct from expected_item then raise exception 'treasure-vault-oozeform-chair: item readback drift'; end if;
  select (to_jsonb(r)||jsonb_build_object('uuid',r.uuid::text))-'{id,created_at,updated_at,search_tsv}'::text[] into saved from public.creature r where r.id=creature_id;
  if saved is distinct from expected_creature then raise exception 'treasure-vault-oozeform-chair: creature readback drift'; end if;
  select coalesce(jsonb_object_agg(r.id::text,to_jsonb(r)-'{updated_at,search_tsv}'::text[]),'{}') into saved from public.item r where r.id<>item_id;
  if saved is distinct from items_before then raise exception 'treasure-vault-oozeform-chair: unrelated item drift'; end if;
  select coalesce(jsonb_object_agg(r.id::text,to_jsonb(r)-'{updated_at,search_tsv}'::text[]),'{}') into saved from public.creature r where r.id<>creature_id;
  if saved is distinct from creatures_before then raise exception 'treasure-vault-oozeform-chair: unrelated creature drift'; end if;
  for dependency in select value from jsonb_array_elements(spec->'dependencies') loop
    execute format('select to_jsonb(r)||jsonb_build_object(''uuid'',r.uuid::text) from public.%I r where r.id=$1',dependency->>'table') into saved using (dependency->>'id')::bigint;
    if (saved-'updated_at') is distinct from dependencies_before->((dependency->>'table')||':'||(dependency->>'id')) then raise exception 'treasure-vault-oozeform-chair: final dependency drift'; end if;
  end loop;
  for source_spec in select value from jsonb_array_elements(spec->'sources') loop
    select to_jsonb(s)-'updated_at' into saved from public.content_source s where s.id=(source_spec->>'id')::bigint;
    if saved is distinct from sources_after->(source_spec->>'id') then raise exception 'treasure-vault-oozeform-chair: final source drift'; end if;
  end loop;
  if exists(select 1 from public.content_update u where coalesce(u.status->>'state','PENDING') not in ('APPROVED','REJECTED') and (
  (u.type='content-source' and exists(select 1 from jsonb_array_elements(spec->'sources') s where u.ref_id=(s->>'id')::bigint or u.data->>'id'=s->>'id' or u.data->>'name'=s->>'name'))
  or exists(select 1 from jsonb_array_elements(spec->'dependencies') d where u.type=d->>'queue_type' and (u.ref_id=(d->>'id')::bigint or u.data->>'id'=d->>'id' or u.data->>'uuid'=d#>>'{expected,uuid}' or ((u.content_source_id=(d#>>'{expected,content_source_id}')::bigint or u.data->>'content_source_id'=d#>>'{expected,content_source_id}') and lower(btrim(u.data->>'name'))=lower(btrim(d#>>'{expected,name}')))))
  or (u.type in ('item','creature') and (u.data->>'uuid'=spec#>>array[u.type,'uuid'] or u.ref_id=case when u.type='item' then item_id else creature_id end or u.data->>'id'=case when u.type='item' then item_id::text else creature_id::text end or ((u.content_source_id=16 or u.data->>'content_source_id'='16') and lower(btrim(u.data->>'name'))=lower(btrim(spec#>>array[u.type,'name'])))))
)) then raise exception 'treasure-vault-oozeform-chair: final pending content requires review'; end if;
end $import$;
$historical_original_dual$;
end $historical_dual$;
